mapper.select:
select fur.id, fur.file_task_id, fur.file_task_name, fur.user_id,
(select real_name from auth_info where user_id = fur.user_id AND auth_status = '5' order by auth_time desc limit 1) user_name,
fur.user_group_ids, fur.competition_series_id, fur.competition_name,fur.competition_stage_id, fur.competition_stage_name,
fur.competition_track_name, fur.competition_track_code, fur.second_level_code, fur.second_level_name, fur.leader_teacher_id, fur.team_code, fur.team_name,
fur.guide_teacher, fur.upload_time, fur.total_size, fur.file_info, fur.del_flag, fur.create_by, fur.create_time, fur.update_by, fur.update_time, fur.remark,fur.upload_operation_type, fur.org_id
from file_upload_record fur

    and fur.del_flag = '0'
     and fur.file_task_id = #{fileTaskId}
     and fur.file_task_name like concat('%', #{fileTaskName}, '%')
     and fur.competition_series_id = #{competitionSeriesId}


        and fur.competition_name like concat('%', #{competitionName}, '%')



        and fur.competition_track_name like concat('%', #{competitionTrackName}, '%')

     and competition_track_code = #{competitionTrackCode}

        and fur.second_level_code = #{secondLevelCode}



        and fur.second_level_name like concat('%', #{secondLevelName}, '%')


        and fur.leader_teacher_id = #{leaderTeacherId}


        and fur.leader_teacher_id IN
        (select distinct user_id from auth_info where real_name like concat('%', #{leaderTeacherName}, '%') AND auth_status = '5')


        and fur.team_code = #{teamCode}



        and fur.team_name like concat('%', #{teamName}, '%')



        and fur.guide_teacher like concat('%', #{guideTeacher}, '%')


        and fur.upload_time >= #{uploadTimeStart}


        and fur.upload_time <= #{uploadTimeEnd}


        and fur.user_id in (select distinct user_id from auth_info where auth_status = '5' and real_name like concat('%', #{userName}, '%'))

     and fur.total_size = #{totalSize}
     and fur.file_info = #{fileInfo}

        and fur.user_id = #{userId}


        and fur.user_group_ids = #{userGroupIds}


        and fur.upload_operation_type = #{uploadOperationType}


        and fur.upload_operation_type != #{uploadOperationTypePC}


order by fur.upload_time desc

select fur.id, fur.file_task_id, fur.file_task_name, fur.user_id, (select real_name from auth_info where user_id = fur.user_id AND auth_status = '5' order by auth_time desc limit 1) user_name, fur.user_group_ids, fur.competition_series_id, fur.competition_name,fur.competition_stage_id, fur.competition_stage_name, fur.competition_track_name, fur.competition_track_code, fur.second_level_code, fur.second_level_name, fur.leader_teacher_id, fur.team_code, fur.team_name, fur.guide_teacher, fur.upload_time, fur.total_size, fur.file_info, fur.del_flag, fur.create_by, fur.create_time, fur.update_by, fur.update_time, fur.remark,fur.upload_operation_type, fur.org_id from file_upload_record fur
and fur.file_task_id = #{fileTaskId}
and fur.user_id = #{userId}
order by fur.create_time desc limit 1

mapper.update:
update file_upload_record
file_task_id = #{fileTaskId}, file_task_name = #{fileTaskName}, user_id = #{userId}, user_group_ids = #{userGroupIds}, competition_series_id = #{competitionSeriesId}, competition_name = #{competitionName}, competition_stage_id = #{competitionStageId}, competition_stage_name = #{competitionStageName}, competition_track_name = #{competitionTrackName}, competition_track_code = #{competitionTrackCode}, second_level_code = #{secondLevelCode}, second_level_name = #{secondLevelName}, leader_teacher_id = #{leaderTeacherId}, team_code = #{teamCode}, team_name = #{teamName}, guide_teacher = #{guideTeacher}, upload_time = #{uploadTime}, total_size = #{totalSize}, file_info = #{fileInfo}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}, upload_operation_type = #{uploadOperationType}, org_id = #{orgId},
where id = #{id}
